--region import
local StoreUtils = import('Game.UI.Store.StoreUtils')
--endregion import

--region define
local KTool = CS.Engine.Lib.KTool
local Animator = CS.UnityEngine.Animator
local UIModule = CS.Engine.UI.UIModule
-- 页签类型
local TagType = {
    Discount = 1, -- 折扣标签
    Activity = 2, -- 活动标签
}
--endregion define

---@class StoreChestCell
---@field Txtoriginal                   	UnityEngine.RectTransform
---@field OriPriceMask                  	UnityEngine.RectTransform
---@field ActivityTabelGroup            	UnityEngine.RectTransform
---@field OriPriceTxt                   	UnityEngine.RectTransform
---@field OriPriceIcon                  	UnityEngine.RectTransform
---@field CurPriceTxt                   	UnityEngine.RectTransform
---@field CurPriceIcon                  	UnityEngine.RectTransform
---@field TxtLock                       	UnityEngine.RectTransform
---@field OriPrice                      	UnityEngine.RectTransform
---@field CurPrice                      	UnityEngine.RectTransform
---@field DiscountTxtNumber             	UnityEngine.RectTransform
---@field StockTxtNumber                	UnityEngine.RectTransform
---@field Txtday                        	UnityEngine.RectTransform
---@field TimerGroup                    	UnityEngine.RectTransform
---@field GoodQuality                   	UnityEngine.RectTransform
---@field ImgIcon                       	UnityEngine.RectTransform
---@field TxtDesc1                      	UnityEngine.RectTransform
---@field GroupDesc2                    	UnityEngine.RectTransform
---@field LockGroup                     	UnityEngine.RectTransform
---@field FinishGroup                   	UnityEngine.RectTransform
---@field DisableMask                   	UnityEngine.RectTransform
---@field PriceGroup                    	UnityEngine.RectTransform
---@field FreeGroup                     	UnityEngine.RectTransform
---@field DiscountGroup                 	UnityEngine.RectTransform
---@field ImgCode                       	UnityEngine.RectTransform
---@field ImgbgState                    	UnityEngine.RectTransform
---@field obj                           	UnityEngine.RectTransform
---@field ImgNew                        	UnityEngine.RectTransform
local StoreChestCell = Class("StoreChestCell")

--region lifecycle
function StoreChestCell:__init()
    self._cellData = nil
end

function StoreChestCell:__delete()
    self._cellData = nil
end

function StoreChestCell:Awake()
    SetButtonAction(self.obj, Bind(self, self.CellClickHandler))
end

function StoreChestCell:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end
--endregion lifecycle

--region public
---刷新cell
---@param openId StoreConstants.OpenIds
---@param data StoreChestDojo
function StoreChestCell:RefreshCell(openId, data)
    self._openId = openId
    self._cellData = data

    self:RefreshCellState(data)
    self:RefreshTimeGroup(data)
    self:RefreshGoods(data)
    
end

---刷新剩余时间
function StoreChestCell:RefreshTimeGroup(data)
    KTool.SetActive(self.TimerGroup, data.nextRefreshLeftSeconds > 0)
    if data.nextRefreshLeftSeconds > 0 then
        CfUtils.FillText(self.Txtday, StoreUtils.FormatTime(data.nextRefreshLeftSeconds, true))
    end
end
--endregion public

--region private
---cell点击回调
function StoreChestCell:CellClickHandler()
    local data = self._cellData
    local isFree = StoreUtils.ProductIsFree(data)
    local isLocked = StoreUtils.ProductIsLocked(data)
    local isSoldOut = StoreUtils.ProductIsSoldOut(data)
    if isFree then
        UIModule.OpenDialog({ id = Constants.UITypeIds.StoreDailyGiftBag, parameters = {ItemData = data } })
    else
        StoreUtils.OpenChestBuyDialog(self._openId, data)
    end
end

---刷新cell状态
function StoreChestCell:RefreshCellState(data)
    local isSoldOut = StoreUtils.ProductIsSoldOut(data)
    local isLocked, lockedDescr = StoreUtils.ProductIsLocked(data)

    local isGray = isSoldOut or isLocked
    KTool.SetActive(self.DisableMask, isGray)
    KTool.SetActive(self.LockGroup, isLocked)
    KTool.SetActive(self.FinishGroup, isSoldOut)
    
    if isLocked then
        CfUtils.FillText(self.TxtLock, lockedDescr)
    end
end

---刷新道具
function StoreChestCell:RefreshGoods(data)
    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(checkNumber(data.icon))
    if not vo then return end
    

    CfUtils.FillImage(self.ImgIcon, vo.photoPath)
    local name = vo.name
    if checkInt(data.num) > 1 then
        name = string.format('%s x%d', name, checkInt(data.num))
    end
    CfUtils.FillText(self.TxtDesc1, name)
    
    -- 品质
    CfUtils.FillImage(self.GoodQuality, StoreUtils.GetGoodsBgByQuality(vo.quality))
    
    -- 库存
    if checkNumber(vo.stock) == -1 then
        KTool.SetActive(self.GroupDesc2, false)
    else
        KTool.SetActive(self.GroupDesc2, true)
        CfUtils.FillText(self.StockTxtNumber, data.currentStock)
    end
    
    -- 价格
    local isFree = StoreUtils.ProductIsFree(data)
    KTool.SetActive(self.PriceGroup, not isFree)
    KTool.SetActive(self.FreeGroup, isFree)
    CfUtils.SetUISwitchImage(self.ImgbgState, isFree and 2 or 1)
    CfUtils.SetUISwitchImage(self.ImgCode, isFree and 2 or 1)
    if not isFree then
        local currencyVo = GoodsConfMgr:GetInstance():GetGoodsVoById(checkNumber(data.prices[1].currency))
        if data.prices[1].original ~= 0 then
            KTool.SetActive(self.OriPrice, true)
            KTool.SetActive(self.CurPrice, false)
            CfUtils.FillImage(self.OriPriceIcon, currencyVo.photoPath)
            CfUtils.FillText(self.OriPriceTxt, data.prices[1].current)
            CfUtils.FillImage(self.OriPriceMask, currencyVo.photoPath)
            CfUtils.FillText(self.Txtoriginal, data.prices[1].original)
        else
            KTool.SetActive(self.OriPrice, false)
            KTool.SetActive(self.CurPrice, true)
            CfUtils.FillImage(self.CurPriceIcon, currencyVo.photoPath)
            CfUtils.FillText(self.CurPriceTxt, data.prices[1].current)
        end
    end
    
    local tabType = checkInt(data.iconId)
    KTool.SetActive(self.DiscountGroup, false)
    KTool.SetActive(self.ActivityTabelGroup, false)
    if tabType == TagType.Activity then
        KTool.SetActive(self.ActivityTabelGroup, true)
    elseif tabType == TagType.Discount then
        CfUtils.FillText(self.DiscountTxtNumber, data.iconTitle)
        KTool.SetActive(self.DiscountGroup, true)
    end
end
--region private
return StoreChestCell